def contains_nearby_duplicate(nums, k):
    last_seen = {}
    for i, num in enumerate(nums):
        if num in last_seen and i - last_seen[num] <= k:
            return True                                              # a nearby repeat was found
        last_seen[num] = i                                             # always keep the most recent index
    return False


